/// <summary>
/// HSMobileOpsCountRequestSvc's request. Outside system (createHazardCount, cancelHazardCount,
/// getHazardCountStatus): DataAreaId, Reference, WarehouseId, DueUtc (ISO 8601, UTC), Description and
/// ItemsJson [{ItemId, ConfigId, SizeId, ColorId, StyleId, LocationId}]. Handheld (listCounts,
/// getCountItems, getCountResults): DataAreaId, UserName, DeviceId, WarehouseId, MasterId.
/// Supervisor (listCategories, createCount): CategoryId (parent, blank = first level), CountType
/// (Blind, WallToWall, Hazard), Description, CategoriesJson ["RecId", ...], ItemsJson.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountReqRequest
{
    str dataAreaId;
    str userName;
    str deviceId;
    str warehouseId;
    str reference;
    str dueUtc;
    str description;
    str itemsJson;
    str masterId;
    str countType;
    str categoriesJson;
    str categoryId;
}

